public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) {
        return res;
    }
    int n = nums.length;
    boolean[] used = new boolean[n];
    List<Integer> temp = new ArrayList<>(n);
    class Backtrack {
        void dfs() {
            if (temp.size() == n) {
                res.add(new ArrayList<>(temp));
                return;
            }
            for (int i = 0; i < n; i++) {
                if (!used[i]) {
                    used[i] = true;
                    temp.add(nums[i]);
                    dfs();
                    temp.remove(temp.size() - 1);
                    used[i] = false;
                }
            }
        }
    }
    new Backtrack().dfs();
    return res;
}

