public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    // If start equals end, it's trivially reachable
    if (sx == ex && sy == ey) {
        return "can be travelled";
    }

    // Build adjacency list
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length != 4) continue;
            int x1 = p[0], y1 = p[1];
            int x2 = p[2], y2 = p[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                continue;
            }
            // Check if the two points are adjacent (Manhattan distance of 1)
            if (Math.abs(x1 - x2) + Math.abs(y1 - y2) != 1) {
                continue;
            }
            String a = x1 + "," + y1;
            String b = x2 + "," + y2;
            adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        }
    }

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    String startKey = sx + "," + sy;
    queue.offer(startKey);
    visited.add(startKey);
    String targetKey = ex + "," + ey;

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(targetKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors != null) {
            for (String nb : neighbors) {
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    queue.offer(nb);
                }
            }
        }
    }
    return "cannot be travelled";
}

