private static void backtrack(int depth, int[] sorted, boolean[] visited, int[] current,
                              int[] count, java.util.Set<Integer> perfectSquares) {
    int n = sorted.length;
    if (depth == n) {
        count[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;
        // Skip duplicates: if the same number as previous and previous not used in this level
        if (i > 0 && sorted[i] == sorted[i - 1] && !visited[i - 1]) {
            continue;
        }
        if (depth > 0) {
            int sum = current[depth - 1] + sorted[i];
            if (!perfectSquares.contains(sum)) {
                continue;
            }
        }
        visited[i] = true;
        current[depth] = sorted[i];
        backtrack(depth + 1, sorted, visited, current, count, perfectSquares);
        visited[i] = false;
    }
}

