    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // Step 1: find the first index i from right where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) { // no higher permutation
        return -1;
    }
    // Step 2: find j, the smallest digit greater than digits[i] to the right
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // Step 3: swap i and j
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Step 4: reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
