public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current <= n / 10) { // can go deeper in prefix
            current *= 10;
        } else {
            // move to next number in lexicographical order
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

